INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R1-001', 1, 'Which international organization, founded in 1945 in San Francisco, currently has its main headquarters on international territory in New York City and comprises 193 member states?', 'The United Nations (UN)', 'UN Charter Archives', 'available') ON CONFLICT (tag) DO NOTHING;
