INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R1-005', 1, 'Which desert in southern Africa covers most of Botswana, parts of Namibia, and regions of South Africa, known for the San bushmen and the Okavango Delta?', 'The Kalahari Desert', 'African Geographical Review', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R1-006', 1, 'What is the official term for the study and collection of postage stamps and postal history?', 'Philately', 'Royal Philatelic Society', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R1-007', 1, 'Which strait separates the Spanish enclave of Gibraltar from Morocco, connecting the Atlantic Ocean to the Mediterranean Sea?', 'Strait of Gibraltar', 'Maritime Geography Handbook', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R1-008', 1, 'Named after an Italian statesman and prime minister, which international airport serves Rome as its primary aviation hub?', 'Leonardo da Vinci–Fiumicino Airport', 'International Civil Aviation Organization', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R1-009', 1, 'What chemical element, atomic number 74, has the highest melting point of all refractory metals at 3,422 degrees Celsius and is mined primarily as wolframite?', 'Tungsten (Wolfram)', 'IUPAC Periodic Table', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R1-010', 1, 'Which island nation in the Indian Ocean has Malé as its capital and is the lowest-lying nation on Earth with an average ground elevation of 1.5 meters?', 'Maldives (Republic of Maldives)', 'World Factbook', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R2-001', 2, 'Discovered in 2012 at CERN''s Large Hadron Collider, which fundamental boson gives mass to other elementary particles through its quantum field mechanism?', 'The Higgs Boson', 'CERN / Nature 2012', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R2-002', 2, 'In genetics, what revolutionary bacterial defense system did Jennifer Doudna and Emmanuelle Charpentier adapt into a programmable molecular scissor for genome editing?', 'CRISPR-Cas9', 'Nobel Prize in Chemistry 2020', 'available') ON CONFLICT (tag) DO NOTHING;
