INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R2-005', 2, 'Which programming language, created by Guido van Rossum and first released in 1991, took its name not from a reptile, but from a British comedy troupe?', 'Python (Monty Python''s Flying Circus)', 'Python Software Foundation', 'available') ON CONFLICT (tag) DO NOTHING;
INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R2-006', 2, 'Which fundamental physical constant, approximately equal to 6.626 x 10^-34 Joule-seconds, relates the energy of a photon to its frequency?', 'Planck''s Constant (h)', 'CODATA Fundamental Physical Constants', 'available') ON CONFLICT (tag) DO NOTHING;
