INSERT INTO public.questions (tag, round, question, answer, source, status) VALUES ('R2-008', 2, 'In computer networking, which protocol operating at port 443 secures internet communication through cryptographic asymmetric handshakes and symmetric encryption?', 'HTTPS (Hypertext Transfer Protocol Secure / TLS)', 'IETF RFC 8446', 'available') ON CONFLICT (tag) DO NOTHING;
